"""Financial ecosystem: role-level public study, never private account discovery."""
from .tech_industry import TechIndustry
LAYERS=[('Public framework',['Central banks','Financial regulators','Public treasury and taxes','Deposit and consumer protection']),('Market infrastructure',['Settlement systems','Clearing systems','Securities infrastructure','Payment networks']),('Institutions',['Retail banks','Credit unions and cooperatives','Development banks','Community finance']),('Services',['Deposits and savings','Lending and credit','Insurance and pensions','Investment services']),('Channels',['Branches and agents','Cards and ATMs','Mobile money','Fintech and online banking']),('Economic activity',['Wages and livelihoods','Trade and small business','Remittances','Public procurement']),('Provision and inclusion',['Benefits and social protection','Debt advice and relief','Affordable access','Financial and digital skills']),('People and needs',['Households and children','Low-income communities','Small organisations','Creators and workers'])]
SOURCES=[{'title':'Bank of England: money creation','url':'https://www.bankofengland.co.uk/quarterly-bulletin/2014/q1/money-creation-in-the-modern-economy','note':'Central-bank explanation of commercial-bank money creation; not a complete account of every financial system.'},{'title':'World Bank financial inclusion','url':'https://www.worldbank.org/ext/en/topic/financial-sector/financial-inclusion','note':'Study access, affordability and resilience; inclusion indicators do not alone establish individual welfare.'},{'title':'ECB public news feeds','url':'https://www.ecb.europa.eu/home/html/rss.en.html','note':'Publisher feeds supply dated statements, publications and announcements.'}]
FEEDS=[('Bank of England','https://www.bankofengland.co.uk/rss/news'),('ECB','https://www.ecb.europa.eu/rss/press.html')]
class FinanceIndustry(TechIndustry):
 def __init__(self,data):super().__init__(data,'financial',LAYERS,SOURCES,FEEDS)
 def view(self):
  state=super().view();state['scope']='Role-level financial ecosystem and public publisher updates; no account balances, payments, private transactions or complete institution inventory.'
  state['four_way']={'true_good':'Daily provision, fair access, resilience and livelihoods for vulnerable people and creators.','false_good':'Profit or stability concealing deprivation, or disruption presented as relief while benefits and wages are lost.','false_evil':'Condemning mutual aid, reform or free access merely because it reduces revenue.','true_evil':'Fraud, exploitation, coercive deprivation or destroying access to necessities.'};return state
